FestivalAnimalSelectionScene::FestivalAnimalSelectionScene(SceneTransitionOwner next,
    GameStateSaveImage * image, MaryFestivalAnimalKind kind)
    : core(new FestivalAnimalSelectionCore(next, image, kind))
{
}





FestivalAnimalSelectionScene::~FestivalAnimalSelectionScene()
{
}

SceneTransitionOwner FestivalAnimalSelectionScene::Run()
{
    return RunFestivalAnimalSelectionCore(core.Get());
}

FestivalAnimalSelectionResult FestivalAnimalSelectionScene::GetSelectionResult() const
{
    return core.Get()->result;
}



